const insertBefore = {
  "r-5": ["r-logical-vectors", "r-tidy"],
  "r-6": ["r-database"],
  "r-7": ["r-eda"],
  "r-advanced": ["r-model-grid"],
  "r-9": ["r-quarto"],
};

Object.assign(window.RZH_COURSE_ANALOGIES, {
  "r-logical-vectors": "筛选条件像一道筛网，TRUE 留在上面，FALSE 漏下去，NA 则提醒你“这里还不知道”。",
  "r-tidy": "整洁数据像一盒分格收纳的积木：一行一件东西，一列一种属性，一格只放一个值。",
  "r-database": "读取不同数据源像去不同仓库取货，先看清单和货架结构，再决定搬什么回来。",
  "r-eda": "探索性分析像看地图找路：先看大方向，再放大局部，发现异常就换个角度继续看。",
  "r-model-grid": "比较模型像把几张地图并排摊在桌上，尺度和路线必须一致，比较才有意义。",
  "r-quarto": "Quarto 文档像会自动更新的实验记录本，数据和代码一改，正文里的结果也跟着重算。",
});

const moduleMap = new Map(r4dsModules.map((module) => [module.id, module]));
const ordered = [];
for (const module of window.RZH_COURSE_MODULES) {
  for (const addId of insertBefore[module.id] || []) {
    const addition = moduleMap.get(addId);
    if (addition) ordered.push(addition);
  }
  ordered.push(module);
}
window.RZH_COURSE_MODULES = ordered.map((module, index) => ({ ...module, number: index + 1 }));

;
