const standardThemeFunction = (id, title, summary, bestFor) => ({
  id,
  name: `${title}()`,
  package: "ggplot2",
  category: "可视化",
  aliases: ["图形主题", "ggplot主题", title],
  summary,
  syntax: `${title}(base_size = 11, base_family = "", header_family = NULL, base_line_size = base_size/22, base_rect_size = base_size/22, ink = "black", paper = "white", accent = "#3366FF")`,
  returns: "返回可叠加到 ggplot 对象的主题设置；不会改变数据、几何图层或统计结果。",
  level: "入门",
  example: `ggplot(dat, aes(age, bmi, color = sex)) +\n  geom_point() +\n  ${title}(base_size = 12)`,
  output: `使用 ${title}() 调整背景、网格、字体和线条等外观。`,
  params: [
    ["base_size", "整张图的基础字号，其他字号通常据此按比例派生。", "11", "论文图常从 10-12 开始调整。"],
    ["base_family", "基础字体族；中文图要确认字体实际可用。", '""', "不要只凭名称猜测系统中已有字体。"],
    ["header_family", "标题和分面标题使用的字体族；NULL 表示沿用默认规则。", "NULL", "通常无需单独设置。"],
    ["base_line_size", "基础线宽。", "base_size/22", "与 base_size 联动变化。"],
    ["base_rect_size", "矩形边框的基础线宽。", "base_size/22", "影响面板、图例键等矩形元素。"],
    ["ink", "文字、轴线和主要前景元素的基础颜色。", '"black"', "深色背景主题要换成浅色。"],
    ["paper", "背景或“纸张”基础颜色。", '"white"', "论文图通常保持白色。"],
    ["accent", "主题中用于强调元素的基础颜色。", '"#3366FF"', "可结合自己的配色方案调整。"],
  ],
  tips: [
    "主题只改外观，不改变数据、统计量或图层含义。",
    "优先用一个完整主题，再用 theme() 微调少数元素。",
  ],
  related: ["ggplot", "theme", "element_text", "ggsave"],
});

