    syntax: "vfold_cv(data, v = 10, repeats = 1, strata = NULL, ...)", returns: "返回 rset 重采样对象。",
    example: `vfold_cv(training(split), v = 5, strata = outcome)`, output: "生成 5 个训练/验证拆分。",
    params: [["data", "训练数据。", "必填"], ["v", "折数。", "默认 10"], ["repeats", "重复次数。", "默认 1"], ["strata", "分层变量。", "推荐使用"]],
