    syntax: "workflow(preprocessor = NULL, spec = NULL, ...)", returns: "返回 workflow 对象。",
    example: `workflow(preprocessor = rec, spec = logistic_reg())`, output: "组合预处理配方与模型。",
    params: [["preprocessor", "recipe 或公式。", "推荐 recipe"], ["spec", "parsnip 模型定义。", "必填"]],
