functions.push(...(window.RZH_EXTRA_FUNCTIONS || []));
functions.push(...(window.RZH_EXTRA_FUNCTIONS_2 || []));
functions.push(...(window.RZH_EXTRA_FUNCTIONS_3 || []));
functions.push(...(window.RZH_EXTRA_FUNCTIONS_4 || []));
functions.push(...(window.RZH_EXTRA_FUNCTIONS_5 || []));
functions.push(...(window.RZH_GUIDE_FUNCTIONS || []));
functions.push(...(window.RZH_ADVANCED_GUIDE_FUNCTIONS || []));
functions.push(...(window.RZH_COURSE_FUNCTIONS || []));
functions.push(...(window.RZH_MANUAL_FUNCTIONS || []));

const uniqueFunctionsById = new Map();
functions.forEach((item) => {
  const existing = uniqueFunctionsById.get(item.id);
  if (!existing) {
    uniqueFunctionsById.set(item.id, item);
    return;
  }
  existing.course = Boolean(existing.course || item.course);
  existing.aliases = [...new Set([...(existing.aliases || []), ...(item.aliases || [])])];
  if (item.source) {
    const sources = String(existing.source || "")
      .split(" · ")
      .filter(Boolean);
    for (const source of item.source.split(" · ")) {
      if (source && !sources.includes(source)) sources.push(source);
    }
    existing.source = sources.join(" · ");
  }
  if (existing.catalogEntry === undefined && item.catalogEntry !== undefined) existing.catalogEntry = item.catalogEntry;
});
functions.splice(0, functions.length, ...uniqueFunctionsById.values());

const courseFunctionIds = new Set([
  "read.csv",
  "filter",
  "select",
  "mutate",
  "group_by",
  "summarise",
  "left_join",
  "table",
  "mean",
  "median",
  "sd",
  "var",
  "quantile",
  "t.test",
  "chisq.test",
  "prop.test",
  "glm",
  "coxph",
  "survfit",
  "ggsurvplot",
  "ggplot",
  "aes",
  "lm",
  "aov",
  "wilcox.test",
  "kruskal.test",
  "fisher.test",
  "cor.test",
  "summary",
  "str",
  "is.na",
  "na.omit",
  "order",
  "merge",
  "subset",
  "ifelse",
  "lapply",
  "sapply",
  "shapiro.test",
  "leveneTest",
  "xtabs",
  "clogit",
]);
functions.forEach((item) => {
  item.course = item.course === true || courseFunctionIds.has(item.id);
});

