const findFunction = (id) => functions.find((item) => item.id === id);

function packageSlug(name) {
  return String(name).toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-|-$/g, "");
}

function buildPackageCatalog() {
  const infoByName = new Map(packageGuides.map((item) => [item.name, item]));
  const packageNames = [...new Set([...functions.map((item) => item.package), ...infoByName.keys()])]
    .filter((name) => name && name !== "自定义函数");
  return packageNames.map((name) => {
    const info = infoByName.get(name) || {};
    const ownFunctions = functions.filter((item) => item.package === name);
    const listedFunctions = info.functions || [];
    const preferred = listedFunctions.filter((id) => functions.some((item) => item.id === id));
    const orderedIds = [...new Set([...preferred, ...ownFunctions.map((item) => item.id)])];
    const unlinkedFunctions = listedFunctions.filter((id) => !functions.some((item) => item.id === id));
    return {
      id: packageSlug(name),
      name,
      title: info.title || `${name} 程序包`,
      category: info.category || "其他程序包",
      level: info.level || "常用",
      builtin: Boolean(info.builtin),
      summary: info.summary || `当前词库收录了 ${ownFunctions.length} 个属于 ${name} 的函数。展开后可以查看函数和安装方式。`,
      useCases: info.useCases || ["查看该包在本站收录的函数", "按函数名继续查看参数和示例"],
      functionIds: orderedIds,
      unlinkedFunctions,
      functionCount: orderedIds.length,
    };
  }).sort((a, b) => {
    if (a.builtin !== b.builtin) return a.builtin ? -1 : 1;
    const aCurated = infoByName.has(a.name);
    const bCurated = infoByName.has(b.name);
    if (aCurated !== bCurated) return aCurated ? -1 : 1;
    return a.name.localeCompare(b.name);
  });
}

const escapeHtml = (value) =>
  String(value)
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;")
    .replaceAll("'", "&#039;");

function inlineRichText(value) {
  return escapeHtml(value).replace(/`([^`]+)`/g, "<code>$1</code>");
}

