function handleHomeLearning(element) {
  const route = element.dataset.route;
  if (element.dataset.workflow) {
    state.workflow = element.dataset.workflow;
    state.workflowCategory = workflows.find((item) => item.id === state.workflow)?.group || "";
  }
  if (element.dataset.basicsTab) state.basicsTab = element.dataset.basicsTab;
  if (element.dataset.category) {
    state.functionCategory = element.dataset.category;
    state.functionPackage = "全部";
    state.functionQuery = "";
  }
  navigate(route);
}

function toggleTeachingCategory(categoryId) {
  state.openTeachingCategory = state.openTeachingCategory === categoryId ? "" : categoryId;
  const route = currentRoute();
  if (route === "home") renderHome();
  else if (route === "learn") renderLearnHub();
  else renderRoute();
  requestAnimationFrame(() => {
    const zone = document.getElementById(route === "learn" ? "teaching-zone-learn" : "teaching-zone-home");
    zone?.scrollIntoView({ behavior: "smooth", block: "start" });
  });
}

function analyzeQuickError(text) {
  const target = document.getElementById("quick-error-result");
  if (!target) return;
  const input = text.trim().toLowerCase();
  if (!input) {
    target.innerHTML = `<span>还没有输入</span><p>请先粘贴一条 R 报错。</p>`;
    return;
  }
  const stopWords = new Set(["error", "the", "not", "for", "with", "and", "has", "can", "was", "are", "this", "that"]);
  const scoreItem = (item) => {
    const phrase = item.error.toLowerCase();
    const words = phrase.match(/[a-z_][a-z0-9_.]{2,}/g) || [];
    let score = input.includes(phrase) ? 100 : 0;
    for (const word of words) {
      if (!stopWords.has(word) && input.includes(word)) score += 7;
    }
    const chinese = item.meaning.match(/[\u4e00-\u9fa5]{2,}/g) || [];
    for (const word of chinese) if (input.includes(word)) score += 4;
    return score;
  };
  const scored = errorCatalog
    .map((item) => ({ item, score: scoreItem(item) }))
    .filter((entry) => entry.score > 0)
    .sort((a, b) => b.score - a.score);
  const bestScore = scored[0]?.score || 0;
  const ranked = scored
    .filter((entry) => entry.score >= Math.max(8, bestScore * 0.35))
    .slice(0, 1);
  if (!ranked.length) {
    target.innerHTML = `
      <span>没有精确匹配</span>
      <p>先检查报错中的对象名、函数名和文件路径。你也可以打开完整报错词典，按“对象、函数、缺失值、文件”等关键词继续查找。</p>
      <button class="button" type="button" data-action="open-error-search" data-query="${escapeHtml(text.trim())}">查看完整报错速查 ${icon("arrow-right")}</button>
    `;
    return;
  }
  target.innerHTML = ranked.map(({ item }, index) => `
    <div class="quick-error-match ${index === 0 ? "primary" : ""}">
      <span>${index === 0 ? "最可能的原因" : "其他可能"}</span>
      <code>${escapeHtml(item.error)}</code>
      <p>${escapeHtml(item.meaning)}</p>
      <ol>${item.checks.slice(0, 3).map((check) => `<li>${escapeHtml(check)}</li>`).join("")}</ol>
      <div class="quick-error-actions">
        ${(item.functions || []).slice(0, 3).map((id) => peekFunctionPill(id)).join("")}
        <button class="button" type="button" data-action="open-error-search" data-query="${escapeHtml(item.error)}">打开完整排查步骤 ${icon("arrow-right")}</button>
      </div>
    </div>
  `).join("");
}

