function teachingCategoryItemMarkup(item, categoryId, context) {
  const className = `teaching-resource${item.level ? " has-level" : ""}`;
  const shared = `
    ${item.level ? `<span class="teaching-resource-level">${escapeHtml(item.level)}</span>` : ""}
    <span class="teaching-resource-copy"><strong>${escapeHtml(item.title)}</strong><small>${escapeHtml(item.note || "")}</small></span>
    ${icon("arrow-right")}
  `;
  if (item.basicsTab) {
    return `<a class="${className}" href="#basics/${escapeHtml(item.basicsTab)}" data-teaching-category="${escapeHtml(categoryId)}">${shared}</a>`;
  }
  if (item.workflow) {
    return `<a class="${className}" href="#workflow/${escapeHtml(item.workflow)}" data-teaching-category="${escapeHtml(categoryId)}">${shared}</a>`;
  }
  const href = item.href === "#course-roadmap" && context === "home" ? "#learn" : item.href;
  return `<a class="${className}" href="${escapeHtml(href)}" data-teaching-category="${escapeHtml(categoryId)}">${shared}</a>`;
}

function teachingCategoryResourcesMarkup(category, context) {
  const items = category.items || [];
  const preferredOrder = ["入门", "进阶", "高阶", "应用", "工具"];
  const levels = preferredOrder.filter((level) => items.some((item) => item.level === level));
  if (!levels.length) {
    return `<div class="teaching-resource-grid">${items.map((item) => teachingCategoryItemMarkup(item, category.id, context)).join("")}</div>`;
  }
  return `
    <div class="teaching-resource-levels">
      ${levels.map((level) => `
        <section class="teaching-resource-level-group">
          <div class="teaching-level-heading"><span>${escapeHtml(level)}</span><small>${items.filter((item) => item.level === level).length} 个专题</small></div>
          <div class="teaching-resource-grid">
            ${items.filter((item) => item.level === level).map((item) => teachingCategoryItemMarkup(item, category.id, context)).join("")}
          </div>
        </section>
      `).join("")}
    </div>
  `;
}

function teachingZoneMarkup(context = "home", limit = teachingCategories.length) {
  const categories = teachingCategories.slice(0, limit);
  return `
    <section class="teaching-zone" id="${context === "learn" ? "teaching-zone-learn" : "teaching-zone-home"}" aria-labelledby="${context}-teaching-title">
      <div class="section-title-row">
        <div>
          <span class="eyebrow">教学专区</span>
          <h2 class="section-title" id="${context}-teaching-title">按学习目标选择内容</h2>
          <p class="section-copy">每个入口都是独立页面。选择方向后，再进入具体课程或专题。</p>
        </div>
        ${context === "home" ? `<a class="text-link" href="#learn">进入完整教学中心 ${icon("arrow-right")}</a>` : ""}
      </div>
      <div class="teaching-category-grid">
        ${categories.map((category, index) => {
          const progress = teachingCategoryProgress(category);
          return `
            <a class="teaching-category-card" href="#learn/category/${category.id}">
              <span class="teaching-category-number">${String(index + 1).padStart(2, "0")}</span>
              <span class="teaching-category-icon">${icon(category.icon || "grid")}</span>
              <span class="teaching-category-copy">
                <strong>${escapeHtml(category.title)}</strong>
                <small>${escapeHtml(category.subtitle)}</small>
              </span>
              <span class="teaching-category-count">${category.items.length} 个入口</span>
              ${context === "learn" ? `
                <span class="teaching-category-progress">
                  <span class="teaching-category-track" role="progressbar" aria-label="${escapeHtml(category.title)}进度" aria-valuenow="${progress.percent}" aria-valuemin="0" aria-valuemax="100"><i style="width:${progress.percent}%"></i></span>
                  <small>${progress.completed} / ${progress.total} ${progress.unit}</small>
                </span>
              ` : ""}
              ${icon("arrow-right")}
            </a>
          `;
        }).join("")}
      </div>
    </section>
  `;
}

function renderTeachingCategory(categoryId) {
  const category = teachingCategories.find((item) => item.id === categoryId);
  if (!category) {
    renderNotFound();
    return;
  }
  const categoryProgress = teachingCategoryProgress(category);
  const progressLabel = categoryProgress.mode === "done" ? "已完成" : "已学习";
  state.activeTeachingCategory = category.id;
  safeWrite("rzh-active-teaching-category", category.id);
  app.innerHTML = `
    <div class="page page-enter">
      <header class="category-hero">
        <div>
          <button class="detail-back" type="button" data-action="go-back">${icon("arrow-left")} 返回上一页</button>
          <span class="eyebrow">教学方向</span>
          <h1>${escapeHtml(category.title)}</h1>
          <p>${escapeHtml(category.detail)}</p>
        </div>
        <aside class="category-audience-card">
          <span>适合谁</span>
          <p>${escapeHtml(category.audience)}</p>
          <strong>${category.items.length}</strong><small>个学习入口</small>
        </aside>
      </header>
      <section class="category-progress-card" aria-label="${escapeHtml(category.title)}学习进度">
        <div class="category-progress-copy">
          <span>本专区学习进度</span>
          <strong>${progressLabel} ${categoryProgress.completed} / ${categoryProgress.total} ${categoryProgress.unit}</strong>
        </div>
        <div class="progress-track" role="progressbar" aria-label="${escapeHtml(category.title)}学习进度" aria-valuenow="${categoryProgress.percent}" aria-valuemin="0" aria-valuemax="100"><span style="width:${categoryProgress.percent}%"></span></div>
        <small>${categoryProgress.mode === "done" ? "完成课程或快速练习后，这里会自动更新。" : "进入并学习本专区中的条目后，这里会自动更新。"}</small>
      </section>
      <section class="section-block">
        <div class="section-title-row">
          <div>
            <h2 class="section-title">从这里开始</h2>
            <p class="section-copy">每个入口会打开独立页面，可随时使用顶部返回按钮回到这里。</p>
          </div>
        </div>
        ${teachingCategoryResourcesMarkup(category, "learn")}
      </section>
      ${category.id === "system" ? `
        ${learningDashboardMarkup()}
        <section class="section-block" id="course-roadmap" aria-labelledby="course-map-title">
          <div class="section-title-row">
            <div>
              <h2 class="section-title" id="course-map-title">完整系统路线</h2>
              <p class="section-copy">按序号学习即可。每课都有目标、示例、函数速览和实践检查。</p>
            </div>
            <span class="badge badge-brand">约 ${courseModules.reduce((sum, module) => sum + module.minutes, 0)} 分钟</span>
          </div>
          ${courseRoadmapMarkup(recommendedCourseLesson())}
        </section>
      ` : ""}
    </div>
  `;
}

