function findGuide(type, id) {
  return learningGuides.find((item) => item.type === type && item.id === id);
}

function guideTypeLabel(type) {
  return type === "method"
    ? "研究方法"
    : type === "model"
      ? "常用模型"
      : type === "plot"
        ? "可视化"
        : type === "parameter"
          ? "参数专题"
          : "教学专题";
}

function guideFunctionMarkup(functionId) {
  const item = findFunction(functionId);
  if (!item) return "";
  return `
    <article class="guide-function-card">
      <div class="guide-function-head">
        <button class="guide-function-title" type="button" data-action="open-function-peek" data-id="${item.id}">
          <code>${escapeHtml(item.name)}</code>${icon("arrow-right")}
        </button>
        ${badge(item.package, "brand")}
      </div>
      <p>${escapeHtml(item.summary)}</p>
      <dl>
        ${resolvedFunctionParameters(item).slice(0, 6).map(([name, description, usage]) => {
          return `<div><dt>${escapeHtml(name)}</dt><dd><span>${escapeHtml(usage)}</span>${escapeHtml(description)}</dd></div>`;
        }).join("")}
      </dl>
      <a class="text-link" href="#function/${item.id}">查看完整参数与示例 ${icon("arrow-right")}</a>
    </article>
  `;
}

function renderGuide(type, id) {
  const guide = findGuide(type, id);
  if (!guide) {
    renderNotFound();
    return;
  }
  const typeLabel = guide.typeLabel || guideTypeLabel(type);
  const definition = guide.definition || guide.overview;
  const features = guide.features || guide.whenUse;
  const concepts = guide.concepts || [];
  const comparison = guide.comparison;
  const readingNotes = guide.readingNotes || [];
  const references = guide.references || [];
  const exampleImage = type === "plot" ? chartImageSource(guide.id) : "";
  const relatedGuides = (guide.related || []).map((relatedId) => learningGuides.find((item) => item.id === relatedId)).filter(Boolean);
  app.innerHTML = `
    <div class="page">
      <button class="detail-back" type="button" data-action="go-back">${icon("arrow-left")} 返回上一页</button>
      <header class="guide-hero">
        <div class="guide-hero-copy">
          <div class="function-tags">${badge(typeLabel, "brand")}${guide.minutes ? badge(`约 ${guide.minutes} 分钟`, "blue") : ""}${guide.aliases.map((alias) => badge(alias)).join("")}</div>
          <h1>${escapeHtml(guide.title)}</h1>
          <p class="guide-lead">${escapeHtml(guide.hero)}</p>
        </div>
        <aside class="guide-audience-card">
          <span>适合谁</span>
          <p>${escapeHtml(guide.audience)}</p>
          <a class="text-link" href="#functions">继续查函数词典 ${icon("arrow-right")}</a>
        </aside>
      </header>

      <section class="guide-primer">
        <div>
          <span>基本概念</span>
          <h2>什么是${escapeHtml(guide.title)}？</h2>
          <p>${escapeHtml(definition)}</p>
        </div>
        <div>
          <span>适用范围</span>
          <h2>主要用途与特点</h2>
          <ul>
            ${features.map((item) => `<li>${icon("check")}<span>${escapeHtml(item)}</span></li>`).join("")}
          </ul>
        </div>
      </section>

      ${concepts.length ? `
        <section class="guide-concept-panel" aria-labelledby="guide-concepts-title">
          <header>
            <span>基础概念拆解</span>
            <h2 id="guide-concepts-title">先弄懂这几个词，再看代码</h2>
            <p>这些概念决定数据怎样组织、结果怎样解释。遇到陌生术语时，可以先回到这里。</p>
          </header>
          <div class="guide-concept-grid">
            ${concepts.map((concept, index) => `
              <article>
                <span>${String(index + 1).padStart(2, "0")}</span>
                <h3>${escapeHtml(concept.term)}</h3>
                <p>${escapeHtml(concept.explain)}</p>
              </article>
            `).join("")}
          </div>
        </section>
      ` : ""}

      ${exampleImage ? `
        <figure class="guide-chart-example">
          <img src="${exampleImage}" alt="${escapeHtml(guide.title)}示例图">
          <figcaption>
            <span>${icon("scale")} 图形示例</span>
            <p>图为使用模拟数据生成的 ${escapeHtml(guide.title)}，用于说明图形结构和读图方法，不代表真实研究结果。</p>
          </figcaption>
        </figure>
      ` : ""}

      <div class="guide-layout">
        <article class="guide-main">
          ${comparison ? `
            <section class="panel guide-section">
              <div class="guide-section-title"><span>对</span><div><h2>${escapeHtml(comparison.title)}</h2><p>${escapeHtml(comparison.note || "把相近概念放在一起比较，重点看研究对象、时间顺序和效应指标。")}</p></div></div>
              <div class="guide-comparison-wrap">
                <table class="guide-comparison-table">
                  <thead><tr>${comparison.headers.map((header) => `<th>${escapeHtml(header)}</th>`).join("")}</tr></thead>
                  <tbody>
                    ${comparison.rows.map((row) => `<tr>${row.map((cell) => `<td>${escapeHtml(cell)}</td>`).join("")}</tr>`).join("")}
                  </tbody>
                </table>
              </div>
            </section>
          ` : ""}

          <section class="panel guide-section">
            <div class="guide-section-title"><span>01</span><div><h2>检查数据结构</h2><p>先确认每一行代表什么，以及变量类型、时间和单位是否适合当前分析。</p></div></div>
            <ul class="guide-check-list">
              ${guide.dataShape.map((item) => `<li>${icon("check")}<span>${escapeHtml(item)}</span></li>`).join("")}
            </ul>
          </section>

          <section class="panel guide-section guide-steps-section">
            <div class="guide-section-title"><span>02</span><div><h2>操作步骤</h2><p>每一步先说明目的，再给出可以修改和运行的示例代码。</p></div></div>
            <div class="guide-steps">
              ${guide.steps.map((step, index) => `
                <article class="guide-step">
                  <span class="guide-step-number">${String(index + 1).padStart(2, "0")}</span>
                  <div class="guide-step-content">
                    <h3>${escapeHtml(step.title)}</h3>
                    <p>${escapeHtml(step.text)}</p>
                    ${step.code ? `
                      <div class="code-block">
                        <button class="copy-button" type="button" data-action="copy" data-copy="${escapeHtml(step.code)}" aria-label="复制示例代码">${icon("copy")}</button>
                        ${escapeHtml(step.code)}
                      </div>
                    ` : ""}
                    ${step.explain ? `<div class="guide-step-explain">${escapeHtml(step.explain)}</div>` : ""}
                  </div>
                </article>
              `).join("")}
            </div>
          </section>

          <section class="panel guide-section">
            <div class="guide-section-title"><span>03</span><div><h2>相关函数</h2><p>点击函数名可以打开中文参数说明，不需要离开当前页面。</p></div></div>
            <div class="guide-function-grid">
              ${guide.functions.map(guideFunctionMarkup).join("")}
            </div>
          </section>

          <section class="panel guide-section guide-two-column">
            <div>
              <h2>使用条件</h2>
              <ul class="guide-check-list compact">
                ${guide.conditions.map((item) => `<li>${icon("shield")}<span>${escapeHtml(item)}</span></li>`).join("")}
              </ul>
            </div>
            <div>
              <h2>如何理解结果</h2>
              <p class="guide-interpretation">${escapeHtml(guide.interpret)}</p>
              ${readingNotes.length ? `<ul class="guide-reading-notes">${readingNotes.map((item) => `<li>${escapeHtml(item)}</li>`).join("")}</ul>` : ""}
            </div>
          </section>

          <section class="panel guide-section">
            <div class="guide-section-title"><span>04</span><div><h2>常见错误</h2><p>运行结果后，还要继续检查数据、模型假设和解释边界。</p></div></div>
            <div class="guide-pitfalls">
              ${guide.pitfalls.map((item, index) => `<div><span>${index + 1}</span><p>${escapeHtml(item)}</p></div>`).join("")}
            </div>
          </section>

          ${guide.practice ? `
            <section class="panel guide-section guide-practice">
              <div class="guide-section-title"><span>练</span><div><h2>练习与自查</h2><p>合上示例，尝试自己写一遍；结果不应只“能运行”，还应经得起来源和结构检查。</p></div></div>
              <p>${escapeHtml(guide.practice)}</p>
              <a class="button" href="#functions">遇到不熟悉的函数，打开中文词典 ${icon("arrow-right")}</a>
            </section>
          ` : ""}

          ${references.length ? `
            <section class="panel guide-section guide-references">
              <div class="guide-section-title"><span>参</span><div><h2>资料依据与延伸阅读</h2><p>优先列出官方文档、方法学指南与报告规范。具体默认值和函数参数仍以你当前安装的 R 包版本为准。</p></div></div>
              <ul>
                ${references.map((reference) => `
                  <li>
                    <a href="${escapeHtml(reference.url)}" target="_blank" rel="noopener noreferrer">${escapeHtml(reference.title)}</a>
                    ${reference.note ? `<span>${escapeHtml(reference.note)}</span>` : ""}
                  </li>
                `).join("")}
              </ul>
            </section>
          ` : ""}
        </article>

        <aside class="guide-aside">
          <section class="panel aside-card">
            <h3>本篇内容</h3>
            <p>${escapeHtml(guide.overview.split("。")[0])}。</p>
          </section>
          <section class="panel aside-card">
            <h3>快速跳转</h3>
            <div class="related-links">
              <a href="#learn"><span>返回教学类型</span>${icon("arrow-right")}</a>
              <a href="#functions"><span>查函数与参数</span>${icon("arrow-right")}</a>
              <a href="#glossary"><span>查专业术语</span>${icon("arrow-right")}</a>
            </div>
          </section>
          ${relatedGuides.length ? `
            <section class="panel aside-card">
              <h3>相关专题</h3>
              <div class="related-links">
                ${relatedGuides.map((item) => `<a href="#guide/${item.type}/${item.id}"><span>${escapeHtml(item.title)}</span>${icon("arrow-right")}</a>`).join("")}
              </div>
            </section>
          ` : ""}
        </aside>
      </div>
    </div>
  `;
}

function renderFunctionsPage(view = "functions") {
  state.functionVisibleLimit = 72;
  const categories = ["全部", ...new Set(functions.map((item) => item.category))];
  const packages = ["全部", ...new Set(functions.map((item) => item.package))].sort();
  const packageCategories = ["全部", ...new Set(packageCatalog.map((item) => item.category))];
  const packageMode = view === "packages";
  app.innerHTML = `
    <div class="page page-enter">
      <header class="page-header">
        <span class="eyebrow">函数与程序包</span>
        <h1 class="page-title">${packageMode ? "R 包目录" : "函数词典"}</h1>
        <p class="page-subtitle">${packageMode ? "按用途或包名查找，再进入独立页面查看安装方式、适用任务和代表函数。" : "按函数用途、名称或 R 包筛选。每张卡片会打开独立详情页。"}</p>
      </header>
      <nav class="library-tabs" aria-label="函数与程序包">
        <a class="library-tab ${!packageMode ? "active" : ""}" href="#functions" aria-current="${!packageMode ? "page" : "false"}">
          ${icon("grid")}函数查询
        </a>
        <a class="library-tab ${packageMode ? "active" : ""}" href="#packages" aria-current="${packageMode ? "page" : "false"}">
          ${icon("database")}R 包查询
        </a>
      </nav>
      ${packageMode ? `
        <div class="toolbar package-toolbar">
          <label class="toolbar-search">
            <span class="sr-only">搜索 R 包</span>
            ${icon("search")}
            <input id="package-search" type="search" value="${escapeHtml(state.packageQuery)}" placeholder="搜索：dplyr、绘图、缺失值、量表…">
          </label>
          <span class="toolbar-note">共 ${packageCatalog.length} 个程序包</span>
          <button class="button" id="clear-package-filters" type="button">${icon("filter")}重置</button>
        </div>
        <div class="filter-row" aria-label="按程序包用途筛选">
          ${packageCategories.map((category) => `
            <button class="filter-chip ${state.packageCategory === category ? "active" : ""}" type="button" data-action="package-category" data-category="${escapeHtml(category)}">${escapeHtml(category)}</button>
          `).join("")}
        </div>
        <div class="results-head">
          <span id="package-result-count"></span>
          <span>点击卡片进入独立 R 包页面</span>
        </div>
        <div class="package-list" id="package-results"></div>
      ` : `
        <div class="toolbar">
          <label class="toolbar-search">
            <span class="sr-only">搜索函数</span>
            ${icon("search")}
            <input id="function-search" type="search" value="${escapeHtml(state.functionQuery)}" placeholder="搜索：均值、去重、Cox、na.rm…">
          </label>
          <label>
            <span class="sr-only">按 R 包筛选</span>
            <select id="package-filter" aria-label="按 R 包筛选">
              ${packages.map((pkg) => `<option ${pkg === state.functionPackage ? "selected" : ""}>${escapeHtml(pkg)}</option>`).join("")}
            </select>
          </label>
          <button class="button" id="clear-function-filters" type="button">${icon("filter")}重置</button>
        </div>
        <div class="filter-row" aria-label="按用途筛选">
          ${categories.map((category) => `
            <button class="filter-chip ${state.functionCategory === category ? "active" : ""}" type="button" data-action="function-category" data-category="${escapeHtml(category)}">${escapeHtml(category)}</button>
          `).join("")}
        </div>
        <div class="results-head">
          <span id="function-result-count"></span>
          <span>点击卡片进入独立函数页面</span>
        </div>
        <div class="function-list" id="function-results"></div>
      `}
    </div>
  `;
  if (packageMode) renderPackageResults();
  else renderFunctionResults();
}

function getFilteredFunctions() {
  const query = state.functionQuery.trim().toLowerCase();
  return functions.filter((item) => {
    const categoryMatch = state.functionCategory === "全部" || item.category === state.functionCategory;
    const packageMatch = state.functionPackage === "全部" || item.package === state.functionPackage;
    const haystack = [
      item.name,
      item.package,
      item.category,
      item.summary,
      item.level,
      ...item.aliases,
      ...resolvedFunctionParameters(item).flat(),
      plainSearchText(item),
    ].join(" ").toLowerCase();
    return categoryMatch && packageMatch && (!query || haystack.includes(query));
  });
}

function getFilteredPackages() {
  const query = state.packageQuery.trim().toLowerCase();
  return packageCatalog.filter((pkg) => {
    const categoryMatch = state.packageCategory === "全部" || pkg.category === state.packageCategory;
    const functionNames = pkg.functionIds
      .map((id) => functions.find((item) => item.id === id)?.name || "")
      .join(" ");
    const haystack = [
      pkg.name,
      pkg.title,
      pkg.category,
      pkg.level,
      pkg.summary,
      ...pkg.useCases,
      functionNames,
      ...pkg.unlinkedFunctions,
    ].join(" ").toLowerCase();
    return categoryMatch && (!query || haystack.includes(query));
  });
}

function renderPackageResults() {
  const result = getFilteredPackages();
  const list = document.getElementById("package-results");
  const count = document.getElementById("package-result-count");
  if (!list || !count) return;
  count.textContent = `找到 ${result.length} 个程序包`;
  list.innerHTML = result.length
    ? result.map((pkg) => {
      const functionCountLabel = pkg.functionCount && pkg.unlinkedFunctions.length
        ? `${pkg.functionCount} 个可查看 · ${pkg.unlinkedFunctions.length} 个索引`
        : pkg.functionCount
          ? `${pkg.functionCount} 个函数可查看`
          : `${pkg.unlinkedFunctions.length} 个代表函数`;
      return `
        <a class="package-card package-card-link" href="#package/${encodeURIComponent(pkg.id)}">
          <span class="package-card-main">
            <span class="package-mark">${escapeHtml(pkg.name.slice(0, 2))}</span>
            <span class="package-card-title">
              <strong>${escapeHtml(pkg.title)}</strong>
              <small>${escapeHtml(pkg.summary)}</small>
            </span>
          </span>
          <span class="package-card-meta">${badge(pkg.category)}${badge(functionCountLabel, "brand")}</span>
          ${icon("arrow-right")}
        </a>
      `;
    }).join("")
    : `<div class="empty-state" style="grid-column:1/-1">${icon("search")}<h3>没有找到匹配程序包</h3><p>可以输入包名、用途或函数名，例如 dplyr、绘图、缺失值。</p></div>`;
}

function renderPackageDetail(id) {
  const pkg = packageCatalog.find((item) => item.id === id);
  if (!pkg) {
    renderNotFound();
    return;
  }
  const installCode = pkg.builtin
    ? "# R 自带程序包，通常无需安装\n# base、stats、utils 等启动后即可使用"
    : `install.packages("${pkg.name}")`;
  const loadCode = pkg.builtin
    ? "# 通常会自动可用；可用 packages::function() 明确来源\nstats::lm"
    : `library(${pkg.name})\n# 或只调用单个函数：${pkg.name}::function_name()`;
  const functionButtons = pkg.functionIds.slice(0, 24).map((functionId) => peekFunctionPill(functionId)).join("");
  const functionNames = pkg.unlinkedFunctions.slice(0, 24)
    .map((name) => `<span class="package-function-name">${escapeHtml(name)}()</span>`)
    .join("");
  app.innerHTML = `
    <div class="page page-enter">
      <button class="detail-back" type="button" data-action="go-back">${icon("arrow-left")} 返回上一页</button>
      <header class="package-detail-hero">
        <span class="package-mark large">${escapeHtml(pkg.name.slice(0, 2))}</span>
        <div>
          <span class="eyebrow">${escapeHtml(pkg.category)} · ${escapeHtml(pkg.level)}</span>
          <h1>${escapeHtml(pkg.title)}</h1>
          <p>${escapeHtml(pkg.summary)}</p>
        </div>
      </header>
      <div class="detail-grid package-detail-grid">
        <main class="detail-main">
          <section class="panel detail-section">
            <h2>适合用来做什么</h2>
            <ul class="guide-check-list">${pkg.useCases.map((item) => `<li>${icon("check")}<span>${escapeHtml(item)}</span></li>`).join("")}</ul>
          </section>
          <section class="panel detail-section">
            <h2>安装与载入</h2>
            <div class="package-code-grid">
              <div><span>安装</span><div class="code-block">${escapeHtml(installCode)}</div></div>
              <div><span>载入</span><div class="code-block">${escapeHtml(loadCode)}</div></div>
            </div>
          </section>
          <section class="panel detail-section">
            <h2>本包常用函数</h2>
            <div class="package-functions">
              ${functionButtons}${functionNames}
              ${!functionButtons && !functionNames ? `<small>常用函数正在补充。</small>` : ""}
            </div>
            <p class="package-note">带箭头的函数可打开中文函数详情。需要避免命名冲突时，使用 ${escapeHtml(pkg.name)}::函数名()。</p>
          </section>
        </main>
        <aside class="detail-aside">
          <section class="panel aside-card"><h3>快速返回</h3><div class="related-links"><a href="#packages"><span>R 包目录</span>${icon("arrow-right")}</a><a href="#functions"><span>函数词典</span>${icon("arrow-right")}</a></div></section>
        </aside>
      </div>
    </div>
  `;
}

function renderFunctionResults() {
  const result = getFilteredFunctions();
  const list = document.getElementById("function-results");
  const count = document.getElementById("function-result-count");
  if (!list || !count) return;
  const visible = result.slice(0, state.functionVisibleLimit);
  const remaining = Math.max(0, result.length - visible.length);
  count.textContent = result.length
    ? `找到 ${result.length} 个函数${remaining ? ` · 当前显示 ${visible.length} 个` : ""}`
    : "没有找到匹配函数";
  list.innerHTML = result.length
    ? `${visible.map(functionCard).join("")}
      ${remaining ? `
        <div class="function-load-more">
          <button class="button" type="button" data-action="load-more-functions">
            ${icon("chevron-down")}
            <span>继续显示 ${Math.min(72, remaining)} 个，还剩 ${remaining} 个</span>
          </button>
          <small>搜索与筛选已覆盖全部 ${result.length} 个条目</small>
        </div>
      ` : `
        <div class="function-list-complete">
          ${icon("check")}<span>已显示全部 ${result.length} 个结果</span>
        </div>
      `}`
    : `<div class="empty-state" style="grid-column:1/-1">${icon("search")}<h3>没有找到匹配条目</h3><p>试试更短的关键词，或重置分类与包筛选。</p></div>`;
}

