function runLoopDemo() {
  const items = [...document.querySelectorAll("[data-loop-item]")];
  const result = document.getElementById("loop-result");
  items.forEach((item) => {
    item.classList.remove("done");
    const status = item.querySelector("span");
    if (status) status.textContent = "等待";
  });
  if (result) result.textContent = "循环开始，每次处理一个文件…";
  items.forEach((item, index) => {
    window.setTimeout(() => {
      item.classList.add("done");
      const status = item.querySelector("span");
      if (status) status.textContent = `已读取 ${120 + index * 18} 行`;
      if (index === items.length - 1 && result) result.textContent = "循环完成：三个文件使用了同一段处理代码。";
    }, 450 * (index + 1));
  });
}

