function renderErrorResults() {
  const container = document.getElementById("error-results");
  if (!container) return;
  const query = state.errorQuery.trim().toLowerCase();
  const matches = errorCatalog.filter((item) => {
    const categoryMatch = state.errorCategory === "全部" || item.category === state.errorCategory;
    const haystack = [item.error, item.category, item.meaning, item.fix, ...item.checks].join(" ").toLowerCase();
    return categoryMatch && (!query || haystack.includes(query));
  });
  container.innerHTML = matches.length
    ? matches.map((item) => `
      <a class="error-card error-card-link" href="#error/${encodeURIComponent(item.id)}">
        <div class="error-card-summary">
          <code>${escapeHtml(item.error)}</code>
          <span>${escapeHtml(item.category)}</span>
          <p>${escapeHtml(item.meaning)}</p>
          ${icon("arrow-right")}
        </div>
      </a>
    `).join("")
    : `<div class="empty-state">${icon("search")}<h3>没有找到匹配报错</h3><p>复制报错中最关键的一行，或先用“对象”“缺失值”“文件”等短词搜索。</p></div>`;
  const count = document.getElementById("error-count");
  if (count) count.textContent = `找到 ${matches.length} 条`;
}

