const allSearchItems = buildSearchItems();

function searchTypeMatches(item) {
  if (state.searchType === "全部") return true;
  if (state.searchType === "函数") return item.type === "函数";
  if (state.searchType === "R包") return item.type === "R包";
  if (state.searchType === "符号") return item.type === "符号";
  if (state.searchType === "术语") return item.type === "术语";
  if (state.searchType === "报错") return item.type === "报错";
  if (state.searchType === "教程") return ["系统课", "入门", "任务", "问题"].includes(item.type);
  return true;
}

function searchMatches(query) {
  const q = query.trim().toLowerCase();
  if (!q) {
    if (state.searchType === "符号") return allSearchItems.filter((item) => item.type === "符号").slice(0, 12);
    if (state.searchType === "报错") return allSearchItems.filter((item) => item.type === "报错").slice(0, 10);
    if (state.searchType === "术语") return allSearchItems.filter((item) => item.type === "术语").slice(0, 10);
    if (state.searchType === "函数") return allSearchItems.filter((item) => item.type === "函数").slice(0, 10);
    if (state.searchType === "R包") return allSearchItems.filter((item) => item.type === "R包").slice(0, 10);
    if (state.searchType === "教程") return allSearchItems.filter((item) => ["系统课", "入门", "任务", "问题"].includes(item.type)).slice(0, 10);
    return [
      allSearchItems.find((entry) => entry.route === "learn/quick"),
      allSearchItems.find((entry) => entry.route === "learn/r-1"),
      ...functions.filter((item) => item.popular).slice(0, 4).map((item) => allSearchItems.find((entry) => entry.route === `function/${item.id}`)),
      ...workflows.slice(0, 3).map((item) => allSearchItems.find((entry) => entry.type === "任务" && entry.title === item.title)),
      ...glossary.slice(0, 3).map((item) => allSearchItems.find((entry) => entry.type === "术语" && entry.title === item[1])),
    ].filter(Boolean).filter(searchTypeMatches);
  }
  const terms = q.split(/\s+/).filter(Boolean);
  const compactQuery = q.replace(/\s+/g, "");
  return allSearchItems
    .map((item) => {
      let score = 0;
      const title = item.title.toLowerCase();
      const compactTitle = title.replace(/\s+/g, "");
      const compactKeywords = item.keywords.replace(/\s+/g, "");
      if (title === q) score += 100;
      if (title.includes(q)) score += 60;
      if (compactTitle.includes(compactQuery)) score += 55;
      if (item.keywords.includes(q)) score += 30;
      if (compactKeywords.includes(compactQuery)) score += 24;
      for (const term of terms) if (item.keywords.includes(term)) score += 8;
      return { item, score };
    })
    .filter((entry) => entry.score > 0)
    .filter((entry) => searchTypeMatches(entry.item))
    .sort((a, b) => b.score - a.score)
    .slice(0, 14)
    .map((entry) => entry.item);
}

function openSearch(query = "") {
  if (!searchDialog.open) searchDialog.showModal();
  globalSearch.value = query;
  state.searchIndex = 0;
  document.querySelectorAll('[data-action="search-type"]').forEach((button) => {
    const active = button.dataset.type === state.searchType;
    button.classList.toggle("active", active);
    button.setAttribute("aria-pressed", String(active));
  });
  renderSearchResults();
  requestAnimationFrame(() => globalSearch.focus());
}

function closeSearch() {
  if (searchDialog.open) searchDialog.close();
}

function renderSearchResults() {
  state.searchItems = searchMatches(globalSearch.value);
  if (!state.searchItems.length) {
    globalResults.innerHTML = `<div class="empty-state">${icon("search")}<h3>没有找到匹配内容</h3><p>试试“生存分析”“缺失值”“量表信度”或直接输入函数名。</p></div>`;
    return;
  }
  if (!globalSearch.value.trim()) {
    globalResults.innerHTML = `<div class="search-section-label">常用入口</div>${state.searchItems.map(searchResultMarkup).join("")}`;
  } else {
    globalResults.innerHTML = `<div class="search-section-label">匹配结果</div>${state.searchItems.map(searchResultMarkup).join("")}`;
  }
  updateSearchSelection();
}

function searchResultMarkup(item, index) {
  return `
    <button class="search-result ${index === state.searchIndex ? "selected" : ""}" type="button" data-action="open-search-result" data-index="${index}">
      <span class="search-result-icon">${escapeHtml(item.symbol)}</span>
      <span class="search-result-copy"><strong>${inlineRichText(item.title)}</strong><span>${inlineRichText(item.subtitle)}</span></span>
      ${badge(item.type)}
    </button>
  `;
}

function updateSearchSelection() {
  globalResults.querySelectorAll(".search-result").forEach((result, index) => {
    result.classList.toggle("selected", index === state.searchIndex);
    if (index === state.searchIndex) {
      result.scrollIntoView({ block: "nearest" });
    }
  });
}

function openSearchResult(index) {
  const item = state.searchItems[index];
  if (!item) return;
  let destination = item.route;
  if (item.workflowId) {
    state.workflow = item.workflowId;
    state.workflowCategory = workflows.find((workflow) => workflow.id === state.workflow)?.group || "";
    destination = `workflow/${item.workflowId}`;
  }
  if (item.packageId) {
    state.packageCategory = "全部";
    state.packageQuery = item.title.split("：")[0].replace(/\s*程序包\s*$/, "");
    destination = `package/${encodeURIComponent(item.packageId)}`;
  }
  if (item.basicsTab) {
    state.basicsTab = item.basicsTab;
    destination = `basics/${item.basicsTab}`;
  }
  if (item.symbolValue) state.symbolFocus = item.symbolValue;
  if (item.glossaryId) {
    state.glossaryCategory = "全部";
    state.glossaryQuery = item.title;
  }
  if (item.errorId) {
    state.errorCategory = "全部";
    state.errorQuery = item.title;
    destination = `error/${encodeURIComponent(item.errorId)}`;
  }
  closeSearch();
  navigate(destination);
}

function showToast(message) {
  toast.textContent = message;
  toast.classList.add("show");
  clearTimeout(showToast.timeout);
  showToast.timeout = setTimeout(() => toast.classList.remove("show"), 2200);
}

async function copyText(text, successMessage = "已复制") {
  try {
    await navigator.clipboard.writeText(text);
  } catch {
    const area = document.createElement("textarea");
    area.value = text;
    area.style.position = "fixed";
    area.style.opacity = "0";
    document.body.appendChild(area);
    area.select();
    document.execCommand("copy");
    area.remove();
  }
  showToast(successMessage);
}

function openMobileNav() {
  document.body.classList.add("nav-open");
  document.getElementById("menu-button").setAttribute("aria-expanded", "true");
}

function closeMobileNav() {
  document.body.classList.remove("nav-open");
  document.getElementById("menu-button")?.setAttribute("aria-expanded", "false");
}

function initTheme() {
  const saved = localStorage.getItem("rzh-theme");
  const preferred = window.matchMedia("(prefers-color-scheme: dark)").matches ? "dark" : "light";
  document.documentElement.dataset.theme = saved || preferred;
  updateBrowserChromeColor();
}

function toggleTheme() {
  const next = document.documentElement.dataset.theme === "dark" ? "light" : "dark";
  document.documentElement.dataset.theme = next;
  localStorage.setItem("rzh-theme", next);
  updateBrowserChromeColor();
  showToast(next === "dark" ? "已切换到深色主题" : "已切换到浅色主题");
}

