document.addEventListener("click", (event) => {
  const teachingLink = event.target.closest("[data-teaching-category]");
  if (teachingLink) {
    state.activeTeachingCategory = teachingLink.dataset.teachingCategory;
    safeWrite("rzh-active-teaching-category", state.activeTeachingCategory);
  }
  const actionElement = event.target.closest("[data-action]");
  if (actionElement) {
    const action = actionElement.dataset.action;
    if (action === "go-back") goBackFromPage();
    if (action === "quick-search") openSearch(actionElement.dataset.query);
    if (action === "home-learning") handleHomeLearning(actionElement);
    if (action === "toggle-teaching-category") toggleTeachingCategory(actionElement.dataset.categoryId);
    if (action === "toggle-home-error") {
      state.homeErrorOpen = !state.homeErrorOpen;
      renderHome();
      requestAnimationFrame(() => {
        document.getElementById("error-analyzer")?.scrollIntoView({ behavior: "smooth", block: "center" });
        document.getElementById("quick-error-input")?.focus();
      });
    }
    if (action === "function-view") {
      state.functionView = actionElement.dataset.view;
      renderFunctionsPage(actionElement.dataset.view || "functions");
    }
    if (action === "load-more-functions") {
      state.functionVisibleLimit += 72;
      renderFunctionResults();
    }
    if (action === "package-category") {
      state.packageCategory = actionElement.dataset.category;
      renderFunctionsPage("packages");
    }
    if (action === "open-error-search") {
      state.errorCategory = "全部";
      state.errorQuery = actionElement.dataset.query || "";
      navigate("errors");
    }
    if (action === "search-type") {
      state.searchType = actionElement.dataset.type;
      document.querySelectorAll('[data-action="search-type"]').forEach((button) => {
        const active = button.dataset.type === state.searchType;
        button.classList.toggle("active", active);
        button.setAttribute("aria-pressed", String(active));
      });
      state.searchIndex = 0;
      renderSearchResults();
    }
    if (action === "goal-workflow") {
      state.workflow = actionElement.dataset.id;
      navigate(`workflow/${actionElement.dataset.id}`);
    }
    if (action === "toggle-favorite") toggleFavorite(actionElement.dataset.id);
    if (action === "set-accent") setAccentTheme(actionElement.dataset.accent);
    if (action === "open-function-peek") openFunctionPeek(actionElement.dataset.id);
    if (action === "close-function-peek") closeFunctionPeek();
    if (action === "open-function-detail") {
      event.preventDefault();
      closeFunctionPeek();
      navigate(`function/${actionElement.dataset.id}`);
    }
    if (action === "save-note") saveNote(actionElement.dataset.id);
    if (action === "delete-note") deleteNote(actionElement.dataset.id);
    if (action === "copy") copyText(actionElement.dataset.copy, "代码已复制");
    if (action === "inspector-select") {
      state.inspector = actionElement.dataset.id;
      renderStructures();
    }
    if (action === "workflow-select") {
      state.workflow = actionElement.dataset.id;
      state.workflowCategory = workflows.find((item) => item.id === state.workflow)?.group || "";
      navigate(`workflow/${actionElement.dataset.id}`);
    }
    if (action === "workflow-category") {
      const group = actionElement.dataset.group;
      navigate(`workflows/${group}`);
    }
    if (action === "basics-tab") {
      state.basicsTab = actionElement.dataset.tab;
      renderBasics();
    }
    if (action === "toggle-course-done") toggleCourseDone(actionElement.dataset.id);
    if (action === "toggle-quick-done") toggleQuickDone(actionElement.dataset.id);
    if (action === "rstudio-panel") selectRStudioPanel(actionElement.dataset.panel);
    if (action === "control-tab") {
      state.controlTab = actionElement.dataset.tab;
      renderControlFlow();
    }
    if (action === "run-loop-demo") runLoopDemo();
    if (action === "glossary-category") {
      state.glossaryCategory = actionElement.dataset.category;
      document.querySelectorAll('[data-action="glossary-category"]').forEach((button) => {
        button.classList.toggle("active", button === actionElement);
      });
      renderGlossaryResults();
    }
    if (action === "color-group") {
      state.colorGroup = actionElement.dataset.group;
      state.colorQuery = "";
      const input = document.getElementById("color-search");
      if (input) input.value = "";
      const families = filteredColorFamilies();
      if (!families.some((item) => item.name === state.colorFamily)) {
        state.colorFamily = families[0]?.name || "";
      }
      renderColorBrowser();
    }
    if (action === "color-family") {
      state.colorFamily = actionElement.dataset.family;
      state.colorQuery = "";
      const input = document.getElementById("color-search");
      if (input) input.value = "";
      renderColorBrowser();
    }
    if (action === "toggle-named-color") {
      const name = actionElement.dataset.color;
      const selected = new Set(state.selectedColors);
      if (selected.has(name)) selected.delete(name);
      else selected.add(name);
      state.selectedColors = [...selected];
      safeWrite("rzh-color-palette", state.selectedColors);
      renderColorBrowser();
    }
    if (action === "clear-color-palette") {
      state.selectedColors = [];
      safeWrite("rzh-color-palette", state.selectedColors);
      renderColorBrowser();
    }
    if (action === "theme-group") {
      state.themeGroup = actionElement.dataset.group;
      state.themeQuery = "";
      const input = document.getElementById("theme-search");
      if (input) input.value = "";
      renderThemeBrowser();
    }
    if (action === "preview-theme") {
      state.themeSelection = actionElement.dataset.id;
      renderThemeBrowser();
    }
    if (action === "error-category") {
      state.errorCategory = actionElement.dataset.category;
      document.querySelectorAll('[data-action="error-category"]').forEach((button) => {
        button.classList.toggle("active", button === actionElement);
      });
      renderErrorResults();
    }
    if (action === "scale-tab") {
      state.scaleTab = actionElement.dataset.tab;
      renderScales();
    }
    if (action === "saved-tab") {
      state.savedTab = actionElement.dataset.tab;
      renderSaved();
    }
    if (action === "score-choice") {
      state.scaleScores[Number(actionElement.dataset.item)] = Number(actionElement.dataset.score);
      updateScaleScore();
    }
    if (action === "load-sample-code") {
      const input = document.getElementById("code-input");
      if (input) {
        input.value = `library(dplyr)\n\ndat <- dat |>\n  filter(!is.na(age)) |>\n  mutate(sex = factor(sex))\n\nmodel <- glm(event ~ age + sex,\n             data = dat,\n             family = binomial())\nsummary(model)`;
        showToast("已载入示例代码");
      }
    }
    if (action === "analyze-code") analyzeCode();
    if (action === "copy-code-input") {
      const input = document.getElementById("code-input");
      if (input) copyText(input.value, "代码已复制");
    }
    if (action === "open-search-result") openSearchResult(Number(actionElement.dataset.index));
  }

  if (event.target.closest("#open-search") || event.target.closest("#mobile-search")) openSearch();
  if (event.target.closest("#close-search")) closeSearch();
  if (event.target.closest("#theme-toggle")) toggleTheme();
  if (event.target.closest("#palette-toggle")) openAccentDialog();
  if (event.target.closest("#close-accent-dialog")) closeAccentDialog();
  if (event.target.closest("#menu-button")) openMobileNav();
  if (event.target.closest("#sidebar-close")) closeMobileNav();
  if (event.target.closest("#mobile-scrim")) closeMobileNav();
  if (event.target === functionPeek) closeFunctionPeek();
  if (event.target === accentDialog) closeAccentDialog();
  if (event.target.closest("#clear-function-filters")) {
    state.functionQuery = "";
    state.functionCategory = "全部";
    state.functionPackage = "全部";
    state.functionVisibleLimit = 72;
    renderFunctionsPage();
  }
  if (event.target.closest("#clear-package-filters")) {
    state.packageQuery = "";
    state.packageCategory = "全部";
    renderFunctionsPage("packages");
  }
  if (event.target.closest(".nav-item") || event.target.closest(".mobile-tabbar a") || event.target.closest(".brand")) {
    closeMobileNav();
  }
});

document.addEventListener("click", (event) => {
  if (event.defaultPrevented || event.button !== 0 || event.metaKey || event.ctrlKey || event.altKey || event.shiftKey) return;
  const link = event.target.closest('a[href^="#"]');
  if (!link || link.target === "_blank" || link.hasAttribute("data-action") || link.classList.contains("skip-link")) return;
  const href = link.getAttribute("href");
  if (!href || href === "#" || href === "#app") return;
  event.preventDefault();
  navigate(href.slice(1));
});

document.addEventListener("submit", (event) => {
  const quickErrorForm = event.target.closest("[data-quick-error-form]");
  if (quickErrorForm) {
    event.preventDefault();
    analyzeQuickError(new FormData(quickErrorForm).get("error")?.toString() || "");
    return;
  }
  const bmiForm = event.target.closest("[data-bmi-demo-form]");
  if (bmiForm) {
    event.preventDefault();
    const formData = new FormData(bmiForm);
    const weight = Number(formData.get("weight"));
    const height = Number(formData.get("height"));
    const result = document.getElementById("bmi-result");
    if (result) {
      if (!(weight > 0 && height > 0)) {
        result.textContent = "请输入有效的体重和身高。";
      } else {
        const bmi = weight / height ** 2;
        const group = bmi < 18.5 ? "偏低" : bmi < 24 ? "正常范围（中国成人常用分组）" : bmi < 28 ? "超重" : "肥胖";
        result.textContent = `BMI = ${bmi.toFixed(1)}，示例分组：${group}。这只是编程演示，不构成医学诊断。`;
      }
    }
    return;
  }
  const demoForm = event.target.closest("[data-control-demo-form]");
  if (demoForm) {
    event.preventDefault();
    const age = Number(new FormData(demoForm).get("age"));
    const result = document.getElementById("control-result");
    if (result) {
      result.textContent = Number.isFinite(age) && age >= 0 && age <= 120
        ? (age >= 18 ? "年龄 ≥ 18：条件为 TRUE，进入 if 分支。" : "年龄 < 18：条件为 FALSE，进入 else 分支。")
        : "请输入 0 到 120 之间的年龄。";
    }
    return;
  }
  const form = event.target.closest("[data-search-form]");
  if (!form) return;
  event.preventDefault();
  const query = new FormData(form).get("query")?.toString().trim() || "";
  if (!query) {
    openSearch();
    return;
  }
  openSearch(query);
});

document.addEventListener("input", (event) => {
  if (event.target.id === "function-search") {
    state.functionQuery = event.target.value;
    state.functionVisibleLimit = 72;
    renderFunctionResults();
  }
  if (event.target.id === "package-search") {
    state.packageQuery = event.target.value;
    renderPackageResults();
  }
  if (event.target.id === "stability-range") updateStability(event.target.value);
  if (event.target.id === "glossary-search") {
    state.glossaryQuery = event.target.value;
    renderGlossaryResults();
  }
  if (event.target.id === "color-search") {
    state.colorQuery = event.target.value;
    renderColorBrowser();
  }
  if (event.target.id === "theme-search") {
    state.themeQuery = event.target.value;
    renderThemeBrowser();
  }
  if (event.target.id === "error-search") {
    state.errorQuery = event.target.value;
    renderErrorResults();
  }
});

document.addEventListener("change", (event) => {
  if (event.target.id === "package-filter") {
    state.functionPackage = event.target.value;
    state.functionVisibleLimit = 72;
    renderFunctionResults();
  }
});

document.addEventListener("click", (event) => {
  const category = event.target.closest('[data-action="function-category"]');
  if (!category) return;
  state.functionCategory = category.dataset.category;
  state.functionVisibleLimit = 72;
  document.querySelectorAll('[data-action="function-category"]').forEach((button) => {
    button.classList.toggle("active", button === category);
  });
  renderFunctionResults();
});

globalSearch.addEventListener("input", () => {
  state.searchIndex = 0;
  renderSearchResults();
});

pageBack?.addEventListener("click", goBackFromPage);
functionPeek?.addEventListener("click", (event) => {
  if (event.target === functionPeek) closeFunctionPeek();
});
searchDialog?.addEventListener("click", (event) => {
  if (event.target === searchDialog) closeSearch();
});
functionPeek?.addEventListener("cancel", () => {
  state.peekFunctionId = null;
});

globalSearch.addEventListener("keydown", (event) => {
  if (event.key === "ArrowDown") {
    event.preventDefault();
    state.searchIndex = Math.min(state.searchIndex + 1, state.searchItems.length - 1);
    updateSearchSelection();
  }
  if (event.key === "ArrowUp") {
    event.preventDefault();
    state.searchIndex = Math.max(state.searchIndex - 1, 0);
    updateSearchSelection();
  }
  if (event.key === "Enter") {
    event.preventDefault();
    openSearchResult(state.searchIndex);
  }
});

document.addEventListener("keydown", (event) => {
  if ((event.metaKey || event.ctrlKey) && event.key.toLowerCase() === "k") {
    event.preventDefault();
    openSearch();
    return;
  }
  if (event.key === "/" && !["INPUT", "TEXTAREA", "SELECT"].includes(document.activeElement.tagName)) {
    event.preventDefault();
    openSearch();
  }
  if (event.key === "Escape") {
    if (functionPeek?.open) closeFunctionPeek();
    if (searchDialog?.open) closeSearch();
    if (accentDialog?.open) closeAccentDialog();
  }
  if (event.key === "Escape" && document.body.classList.contains("nav-open")) closeMobileNav();
});

function handleRouteLocationChange() {
  const route = currentRoute();
  if (route === routeAtLocation) return;
  routeAtLocation = route;
  renderRoute();
}

ensureRouteHistory();
window.addEventListener("popstate", handleRouteLocationChange);
window.addEventListener("hashchange", handleRouteLocationChange);
initTheme();
updateAccentControls();
updateFavoriteCount();
updateContentCounts();
renderRoute();
requestAnimationFrame(() => requestAnimationFrame(() => window.dismissRzhBoot?.()));
window.setTimeout(() => window.dismissRzhBoot?.(), 120);

if ("serviceWorker" in navigator && location.protocol.startsWith("http")) {
  window.addEventListener("load", () => navigator.serviceWorker.register("./sw.js").catch(() => {}));
}
